registerRefData('nsw-cond-n-914',{"id":914,"pan":null,"ref":"DA-741/2022","address":"149 Orchard Road Chester Hill 2162,191 Miller Road Chester Hill 2162","description":"149 Orchard Rd & 191 Miller Rd, Chester Hill","outcome":"approved","outcome_raw":"Approved","outcome_source":"planning_panels","determined":"2023-10-11","notice_url":"https://apps.planningportal.nsw.gov.au/prweb/PRRestService/DocMgmt/v1/PublicDocuments/DATA-WORKATTACH-FILE PEC-DPE-EP-WORK PPSSSH-122!20231011T055126.398 GMT","sha256":"fad911793eccacf0b278839444945d5f022bf6deea0add54a52ca6d6359373ec","pages":31,"layout":"numbered","n":10,"fetched_at":"2026-08-16T23:19:06+00:00","file":"n/914.js","source_page":"https://www.planningportal.nsw.gov.au/planning-panel/149-orchard-rd-191-miller-rd-chester-hill","lga":"CANTERBURY-BANKSTOWN","conditions":[{"label":"1","code":null,"number":"1","title":"PANEL REF - LGA - DA NO. PPSSSH-122 - Canterbury-Bankstown - DA-741/2022","text":"","stage":"general","stage_basis":"heading","page":3},{"label":"2","code":null,"number":"2","title":"","text":"PROPOSED DEVELOPMENT Demolition of existing structures, removal of site vegetation and retention\nof 6 trees, construction of 4 attached warehouse and distribution buildings\nfor 24 hours, 7 days a week operation, ancillary office spaces, awnings,\nassociated site preparation works, vehicular and pedestrian access, car\nparking and landscaping, 2 pylon signs and associated business\nidentification signage","stage":"general","stage_basis":"heading","page":3},{"label":"3","code":null,"number":"3","title":"","text":"STREET ADDRESS Lot 81 DP 1282378, No. 149 Orchard Road, Chester Hill NSW 2162","stage":"general","stage_basis":"heading","page":3},{"label":"4","code":null,"number":"4","title":"APPLICANT/OWNER Dexus Wholesale Management Limited","text":"Tung Hui Chung, Tong Hong Chung and Chung Enterprise Pty Ltd","stage":"general","stage_basis":"heading","page":3},{"label":"5","code":null,"number":"5","title":"TYPE OF REGIONAL","text":"DEVELOPMENT General development over $30 million","stage":"general","stage_basis":"heading","page":3},{"label":"6","code":null,"number":"6","title":"RELEVANT MANDATORY","text":"CONSIDERATIONS\n Environmental planning instruments:\no Biodiversity Conservation Act 2016\no State Environmental Planning Policy (Biodiversity and\nConservation) 2021\no State Environmental Planning Policy (Industry and Employment)\n2021\no State Environmental Planning Policy (Planning Systems) 2021\no State Environmental Planning Policy (Resilience and Hazards)\n2021\no State Environmental Planning Policy (Transport and\nInfrastructure) 2021\no Bankstown Local Environmental Plan 2015 (BLEP 2015)\n Draft environmental planning instruments: Nil\n Development control plans:\no Bankstown Development Control Plan 2015\n Planning agreements: Nil\n Relevant provisions of the Environmental Planning and Assessment\nRegulation 2021\n Coastal zone management plan: Nil\n The likely impacts of the development, including environmental\nimpacts on the natural and built environment and social and economic\nimpacts in the locality\n The suitability of the site for the development\n Any submissions made in accordance with the Environmental Planning\nand Assessment Act 1979 or regulations\n The public interest, including the principles of ecologically sustainable\ndevelopment","stage":"general","stage_basis":"heading","page":3},{"label":"7","code":null,"number":"7","title":"MATERIAL CONSIDERED BY","text":"THE PANEL\n Council Assessment Report: 25 September 2023\n Supplementary Council Assessment Report: 6 October 2023\n Written submissions during public exhibition: nil","stage":"general","stage_basis":"heading","page":3},{"label":"8","code":null,"number":"8","title":"MEETINGS, BRIEFINGS AND","text":"SITE INSPECTIONS BY THE\nPANEL\n Briefing: 6 December 2022\no Panel members: Helen Lochhead (Chair), Stuart McDonald,\nHeather Warton and Bilal El-Hayak\no Applicant representatives: Lydia Gabriel\no Council assessment staff: Stephen Arnold, Christopher Phu and\nIan Woodward\no Department staff: Leanne Harris and Sharon Edwards\n Briefing: 6 March 2023\no Panel members: Annelise Tuor (Chair), Penelope Holloway,\nGlennis James and Charlie Ishac\no Council assessment staff: Stephen Arnold, Christopher Phu,\nGeorge Gouvatsos, Cassandra Gibbons, Priscilla Prakash and Ian\nWoodward\no Department staff: Sung Pak and Timothy Cook\n Briefing: 29 August 2023\no Panel members: Annelise Tuor (Chair), Penelope Holloway,\nGlennis James and Karl Saleh\no Council assessment staff: Stephen Arnold, Christopher Phu,\nDaniel Bushby, Abdel Albaba and Ian Woodward\no Applicant representatives: Paul Neilsen, Asher Richardson, Mark\nWilson and Lorenzo Lun\no Department staff: Lillian Charlesworth and Lisa Foley\n Determination briefing - deferred: 25 September 2023\no Panel members: Annelise Tuor (Chair), Penelope Holloway,\nGlennis James, Karl Saleh and Khal Asfour.\no Council assessment staff: Stephen Arnold, Christopher Phu and\nIan Woodward\no Department staff: Lillian Charlesworth and Lisa Foley\no Applicant representatives: Paul Neilsen, Asher Richardson and\nLorenzo Lun\n Briefing: 9 October 2023\no Panel members: Annelise Tuor (Chair), Penelope Holloway, Karl\nSaleh and Khal Asfour (Glennis James - apology)\no Council assessment staff: Stephen Arnold, Christopher Phu,\nHooman Khakzad and Abdel Albaba\no Department staff: Lillian Charlesworth and Lisa Foley\no Applicant representatives: Paul Neilsen and Asher Richardson","stage":"general","stage_basis":"heading","page":3},{"label":"9","code":null,"number":"9","title":"COUNCIL","text":"RECOMMENDATION Approval","stage":"general","stage_basis":"heading","page":4},{"label":"10","code":null,"number":"10","title":"","text":"DRAFT CONDITIONS Final conditions dated 9 October 2023 are attached as Schedule 2 to the\nDecision and Statement of Reasons.\nThese consent conditions have been imposed after taking into account the matters for consideration in\ndetermining a development application pursuant to s4.15 and in accordance with s4.17 of the Environmental\nPlanning & Assessment Act 1979.\n1. Approved Development.\n1.1. Development must be carried out in accordance with the following approved plans (stamped by\nCouncil) except where the conditions of this consent expressly require otherwise.\nPlan Number Plan Name Dated Revision Prepared By\nDA-002 Site Plan 01.09.2023 U Concept (y)\nArchitecture\nDA-004 Roof Plan 10.07.2023 C Concept (y)\nArchitecture\nDA-005 Demolition Plan 30.06.2022 A Concept (y)\nArchitecture\nDA-006 Signage and Racking\nPlan\n10.07.2023 G Concept (y)\nArchitecture\nDA100 Office Plans (Office\n1)\n07.07.2023 E Concept (y)\nArchitecture\nDA101 Office Plans (Office\n2)\n07.07.2023 E Concept (y)\nArchitecture\nDA102 Office Plans (Office\n3)\n07.07.2023 E Concept (y)\nArchitecture\nDA103 Office Plans (Office\n4)\n07.07.2023 E Concept (y)\nArchitecture\nDA-200 Indicative Section\n(Warehouse 1-4)\n06.09.2023 B Concept (y)\nArchitecture\nDA-201 Elevations\n(Warehouse 1-4)\n06.06.2023 E Concept (y)\nArchitecture\nDA-202 Office Elevations\n(Warehouse 1)\n06.06.2023 E Concept (y)\nArchitecture\nDA-203 Office Elevations\n(Warehouse 2-3)\n06.06.2023 D Concept (y)\nArchitecture\nDA-204 Office Elevations\n(Warehouse 4)\n06.06.2023 D Concept (y)\nArchitecture\nSCHEDULE 2 - CONDITIONS OF CONSENT\nDA-205 Tenant Signage\nElevations\n23.03.2023 A Concept (y)\nArchitecture\n1.2. Before the issue of a construction certificate, the principal c ertifier must ensure the approved\nconstruction certificate plans (and specifications) detail the following required amendments to\nthe approved plans and supporting documentation stamped by Council.\na. The Site Plan as referenced in the table in Condition 1.1 of th is development consent shall\nbe amended to notate the easement as shown in the approved civi l drawing No.\nCO14242.02-DA, dated 29/09/2023, Revision B, prepared by Costin Roe Consulting\nb. The estate entry pylon sign along Orchard Road shall be amended to achieve a maximum\nwidth of 2m and a maximum height of 4m.\nc. The front fence along Orchard Road shall be amended to achieve a maximum height of\n1.8m above the natural ground level.\n1.3. This development consent prevails over any previous development consent to the extent of any\ninconstancy in relation to contamination works.\n1.4. A separate application shall be submitted to Council before the erection of any additional\nsignage unless the proposed signage is \"exempt development\" in accordance with relevant\nlegislation.\n1.5. The acoustic report submitted in support of this application, p repared by Acoustic Dynamics,\ntitled “Operational Noise Emission Assessment, 149 Orchard Road, Chester Hill, NSW, reference\nnumber: 5571R001.JC.220912, dated 12 September 2022 and recommendations in section 5\nforms part of the development consent.\n1.6. Should a noise issue (relating to the development) not previously identified arise (through\ncomplaint or otherwise), the owner/ occupier must, upon request by Council, employ the\nservices of a qualified acoustic consultant who has not previously been involved with the\ndevelopment to undertake a post-occupation assessment of the development and complete an\na c o u s t i c r e p o r t w i t h r e c o m m e n d a t i o n s t o r e c t i f y t h e n o i s e i s s u e. A copy of this acoustic\nassessment report must be submitted to Council for approval and from there noise attenuation\nworks must be implemented. Submission of the acoustic report must be within 30 days from the\ndate requested by Council.\n1.7. Large vehicles are to not enter or exit the site via Orchard Road. The access from Orchard Road\nis restricted to only small vehicles for staff and visitors.\n1.8. Any large vehicles longer than 12.5m are not permitted to turn left when exiting the site via\nMiller Road access. A ‘no left tu rn’ signage for large vehicle exceeding 12.5m in length shall be\ninstalled along the Miller Road driveway access.\nThe Miller Road driveway access shall be designed in accordance with AS 2890.2 with a raised\nmedian island separating the entry and exit.\n2. Conditions relating to the Landowner’s responsibility for Channel and Pipe Management within\nRegistered Easement\n2.1. Sites located adjacent to Council’s drainage easement and/or sites affected by flooding shall\ncomply with the following:\na. A Work As Executed Plan prepared by a registered surveyor, toge ther with certification\nf r o m a q u a l i f i e d p r o f e s s i o n a l C i v i l E n g i n e e r o f t h e c a p a c i t y a nd adequacy of the\nconstructed floodway/flow path shall be obtained before issue of the certificate of\noccupation or occupation of the site.\nb. The Work As Executed information shall be shown on a copy of the approved plans and\nshall include construction information relating to the following:\n1. All relevant natural ground and finish ground levels within the flow path/floodway\nand relevant surrounding levels.\n2. Determination and the extent of the 1 in 100-year water surface level in the\nfloodway / flow path.\nThe above information together w ith the Engineer’s certificatio n shall be submitted to Council\nfor information before issue of an occupation certificate.\nA Restriction as to User under the provision of Section 88E of the Conveyancing Act 1919 shall\nbe registered on the title of the subject property, requiring that:\ni. “A flow path for overland stormwater runoff / floodway, from up stream\nproperties and Council’s Public Road shall be maintained within Council’s\ndrainage easement and constructed stormwater channels boundaries.”\nii. “No trees or shrubs shall be planted within Council’s drainage easement and\nconstructed floodway, unless approved by Council in the landsca pe plan dated\n01.06.2023 issue H.”\niii. “Changes to approved levels and/or the construction of walls an d landscaping\nwithin Council’s drainage easement/constructed floodway boundaries is not\npermitted unless approved by Council”.\niv. “Any fencing constructed across the floodway or overland flow path shall be\nmaintained to allow for the free passage of surface flow of sto rmwater to the\nsatisfaction of Council”.\nv. The landowner shall assume full responsibility for the care, co ntrol, and\nmaintenance of the overland channels and the flood storage areas located\nwithin the subject property. This responsibility shall encompass all aspects of\nmaintenance, repair, and access, consistent with the terms of any relevant laws,\nregulations, and standards.\nvi. The landowner shall, at their own expense, ensure that the over land channels\nand flood storage areas remains in good working condition, free f r o m\nobstructions, and compliant with all applicable safety and envi ronmental\nstandards.\nvii. The Council reserves the right to access and inspect the easement pipe, subject\nto reasonable notice, for the purpose of ensuring compliance with this condition\nand the registered easement.\nviii. The landowner shall provide Council representatives with safe and unobstructed\naccess to the overland channels, flood storage area and pipe located within the\neasement at all reasonable times.\nix. The landowner shall maintain comprehensive records of all maintenance and\nrepair activities related to the overland channels and flood st orage areas,\nincluding dates, descriptions of work performed, and invoices. These records\nshall be made available to Council upon request.\nx. The landowner shall indemnify and hold harmless the Council, it s officers,\nemployees, and agents from any claims, damages, liabilities, co sts, or expenses\narising from or related to the condition, maintenance, or repair of the overland\nchannels, flood storage areas and pipe located within the easement.\nxi. In the event of a breach of this condition, the Council may tak e such actions as\nit deems necessary, including enforcement proceedings, to ensur e compliance\nwith this condition and the terms of any registered Easement.\nNote: The location of the “Flowpath/floodway” shall be shown on the film plan of subdivision\nwhere subdivision is proposed. Where subdivision is not proposed the location of the flow\npath/floodway shall be included on a site plan attached to the Section 88E instrument.\na. Canterbury-Bankstown City Council shall be empowered to release, vary or modify such\nRestriction.\nThe Restriction and Positive Covenant shall be submitted for registration on title following\nsatisfactory construction and certification of the overland flow path / floodway system and\nbefore issue of the occupation certificate or occupation of the site. Evidence of such registration\nshall be submitted to Council\n3. Conditions imposed by Transport for NSW\n3.1. The layout of the proposed car parking areas associated with th e subject development\n(including, driveways, grades, turn paths, sight distance requirements in relation to landscaping\nand/or fencing, aisle widths, aisle lengths, and parking bay dimensions) should be in accordance\nwith AS 2890.1-2004, AS2890.6-2022 and AS 2890.2-2018 for heavy vehicle usage.\n3.2. The developer shall be responsible for all public utility adjus tment/relocation works,\nnecessitated by the above work and as required by the various p ublic utility authorities and/or\ntheir agents.\n3.3. All vehicles are to enter and leave the site in a forward direction and be wholly contained on site\nbefore being required to stop.\n3.4. Before the issue of a construction certificate, the consent hol der must ensure a Construction\nSite Management Plan (CSMP) is prepared before it is provided to and approved by the Certifier.\nThe plan must include the following matters:\na. location and materials for protective fencing and hoardings to the perimeter on the site;\nb. provisions for public safety;\nc. pedestrian and vehicular site access points and construction activity zones;\nd. details of construction traffic management, including proposed truck movements to and\nfrom the site and estimated frequency of those movements, and m easures to preserve\npedestrian safety in the vicinity of the site;\ne. protective measures for on-site tree preservation (including in accordance with AS 4970\nProtection of trees on development sites and Council’s DCP, if applicable) and trees in\nadjoining public domain (if applicable);\nf. details of any bulk earthworks to be carried out;\ng. location of site storage areas and sheds;\nh. equipment used to carry out all works;\ni. a garbage container with a tight-fitting lid;\nj. dust, noise and vibration control measures; and\nk. location of temporary toilets.\nThe consent holder must ensure a copy of the approved construct ion site management plan is\nkept on-site at all times during construction.\n4. Conditions to be Satisfied Before the Issue of a Construction Certificate.\n4.1. Development Contributions of $337,700.00 must be paid for this development before the issue\nof any construction certificate. The contributions are levied a nd applied under the Canterbury\nBankstown Local Infrastructure Contributions Plan 2022 and Sect ion 7.12 of the Environmental\nPlanning and Assessment Act 1979 . The contributions will be used to provide, extend or\naugment public amenities or public services.\nIndexing of the contribution amount to be paid: The development contribution payable will be\nadjusted, at the time of payment, to reflect Consumer Price Index increases which have occurred\nsince the “Consent to operate from date” which appears on the front page of this Determination\nNotice.\nNo construction certificate is to be issued and no construction is to commence until payment of\ndevelopment contributions. The contribution must be paid to Cou ncil before the issue of any\nconstruction certificate. Construction of the development may N OT commence until the\ndevelopment contributions are paid.\nA copy of the development contributions plan is available for i nspection on Council's website\nand at Council's Administration offices in Bankstown and Campsie.\nNOTE: Development contribution amounts are non-refundable if y ou don’t proceed with your\ndevelopment.\n4.2. All fees, levies, bonds and/or contributions as required by thi s Determination Notice must be\npaid to the relevant authority/entity before the issue of a construction certificate.\n4.3. Before the issue of the relevant construction certificate, payme n t o f t h e l o n g s e r v i c e l e v y i s\nrequired, under the Building and Construction industry Long Service Payments Act 1986, section\n34. Evidence of the payment is to be provided to the Certifier. Payment can be calculated using\nthe Levy Portal Calculator at https://longservice.force.com/bci/s/levy-calculator. Payment must\nbe made via the Long Service Levy Portal at https://www.longservice.nsw.gov.au.\n4.4. Before the issue of the relevant construction certificate, a suitably qualified engineer must\nreview the plans which relate to parking facilities and provide written evidence, to the certifier’s\nsatisfaction, that it complies with the relevant parts of AS 28 90 - ‘Parking Facilities - Off-Street\nCarparking’ and Council’s development control plan.\n4.5. The Council approved plans, including demolition plans, must be submitted to Sydney Water for\nassessment. This will determine if the proposed structure(s) wi l l a f f e c t a n y S y d n e y W a t e r\ninfrastructure or if there are additional requirements. Building plan approvals can be submitted\nonline via Sydney Water Tap inTM.\nRefer to www.sydneywater.com.au/tapin for Sydney Water’s Guidelines for building over or\nnext to assets, visit www.sydneywater.com.au ‘Plumbing, building & developing’ then ‘Building\nPlan Approvals’ or call 13000 TAPINTM.\nSydney Water must issue either a Building Plan Assessment letter which states that the\napplication is approved, or requires conditions that must be satisfied by the PCA, or the\nappropriate plans must be stamped by a Water Servicing Coordinator.\n4.6. The building must comply with the Category 1 fire safety provis ions as are applicable to the\nbuilding's proposed use.\nNote: The obligation to comply with the Category 1 fire safety provisions may require building\nwork to be carried out even though none is proposed or required i n r e l a t i o n t o t h i s\nDetermination Notice.\n4.7. If amendments are required that are inconsistent with the approved development, the building\nmust be designed and constructed to provide access and faciliti es for people with a physical\ndisability in accordance with the Building Code of Australia.\nIf, in complying with this condition, amendments to the develop ment are required, the design\nchanges must be submitted to and approved by Council through a modification application\nbefore a construction certificate being issued.\n4.8. Before the issue of a construction certificate, the consent hol der is to ensure that an erosion\nand sediment control plan is prepared in accordance with the fo llowing documents before it is\nprovided to and approved by the certifier:\n1. Council’s development control plan,\n2. the guidelines set out in the NSW Department of Housing manual ‘Managing Urban\nStormwater: Soils and Construction Certificate’ (the Blue Book), and\n3. the ‘Do it Right On-Site, Soil and Water Management for the Construction Industry'\n(Southern Sydney Regional Organisation of Councils and the Natural Heritage Trust).\nThe consent holder must ensure the erosion and sediment control plan is kept onsite at all times\nduring site works and construction.\n4.9. The premises must be ventilated in accordance with the Building Code of Australia and AS1668.1\nand 2 - ‘The Use of Ventilation and Air- Conditioning in Buildi ngs - Mechanical Ventilation in\nBuildings’.\nDetails of any mechanical ventilation and/or air-conditioning s ystem complying with AS1668.1\nand 2 - ‘The Use of Ventilation and Air- Conditioning in Buildi ngs - Mechanical Ventilation in\nBuildings’, the Building Code of Australia and relevant Austral ian Standards must be prepared\nby a suitably qualified person and certified in accordance with Clause A2.2 (a) (iii) of the Building\nCode of Australia, to the satisfaction of the certifier before the issue of a construction certificate.\n4.10. Before the issue of a construction certificate, the mechanical exhaust systems and/or shafts\nmust be designed to allow for the discharge of effluent air above roof level and must be designed\nw i t h c a p a c i t y t o a c c o m m o d a t e e x h a u s t d u c t s a n d m e c h a n i c a l v e n t il a t i o n s y s t e m s f o r a l l\ncommercial tenancies proposed with the potential to become a fo od premises in future.\nSystems must be designed in accordance with AS1668.2 - ‘The Use o f V e n t i l a t i o n a n d A i r -\nconditioning in Buildings - Mechanical Ventilation in Buildings’, and AS1668.1 - ‘The Use of\nMechanical Ventilation and Air-Conditioning in Buildings - Fire and Smoke Control in Multi-\ncompartment Buildings’.\n4.11. Where Council approved cut or fill exceeds 200mm and stable batter of 1 vertical to 3 horizontal\nmaximum grade cannot be achieved, then a masonry or other propr ietary material retaining\nwall, intended and suitable for that purpose, shall be construc ted within the development site.\nNote, filling of the site needs specific approval from Council.\na. The retaining wall shall be located so that it will not impede or obstruct the natural flow\no f s t o r m w a t e r . R e t a i n i n g w a l l s e x c e e d i n g 6 0 0 m m i n h e i g h t s h a l l be designed by an\nappropriately qualified person as defined in the Building and Development Certifiers\nRegulation 2020. Plans and details prepared and signed by an appropriately qualified\nperson as defined in the Building and Development Certifiers Re gulation 2020 are to be\nsubmitted to the certifier before the issue of the construction certificate.\nb. All works associated with the construction of the wall, includi ng backfilling and drainage,\nis to be located wholly within the allotment boundaries.\n4.12. The consent holder shall apply for a Work Permit and obtain app roval from Council, for any of\nthe following applicable engineering works in front of the site, at their own expense:\na. Two heavy Duty VFC at the property boundary one along Orchard R oad, and one along\nMiller Road.\nb. Reconstruction and diversion of Council trunk drainage pipes and diversion pits as per the\napproved plan CO14242.02-DA, dated by 29/09/2023, Revision B, prepared by Costin Roe\nConsulting. The proposed pipe sizes shall not be reduced.\nc. Removal of all redundant driveway surfaces, reinstatement of laybacks to kerb and gutter\nand reshaping of the footway, all associated with redundant VFCs,\nd. Repair of any damage to the public road including the footway o ccurring during building\nworks, and\ne. R e i n s t a t e m e n t o f t h e f o o t w a y r e s e r v e a n d a d j u s t m e n t o r r e l o c a t ion of existing public\nutility services to match the footway design levels as proposed on the approved Work\nPermit. Adjustment or relocation to any public utility services shall be carried out to the\nrequirements of the public utility authority.\nNote: Council is required to prepare a site survey and design in order to determine the necessary\ninformation. The consent holder should make application and pay ment for the Work Permit at\nleast twenty-one (21) days before the information being require d and before the issue of the\nconstruction certificate. The Work Permit must be approved befor e a n y w o r k s c o m m e n c i n g\nwithin the Council Road Reserve or on Council’s assets.\n4.13. As any works within, or use of, the footway or public road for construction purposes requires\nseparate Council approval under Section 138 of the Roads Act 1993 and/or Section 68 of the\nLocal Government Act 1993, Council requires the consent holder to obtain a Works Permit and\no r a R o a d w a y / F o o t p a t h B u i l d i n g O c c u p a t i o n P e r m i t b e f o r e t h e i s s u e o f a n y c o n s t r u c t i o n\ncertificate for this development being issued where one or more of the following will occur,\nwithin, on or over the public footway or public road:\nA PRIVATE CERTIFIER CANNOT ISSUE THESE PERMITS\nWORKS REQUIRING A 'WORKS PERMIT'\na. Dig up, disturb, or clear the surface of a public footway or public road,\nb. Remove or interfere with a structure or tree (or any other vegetation) on a public footway\nor public road,\nc. Connect a road (whether public or private) to a classified road,\nd. Undertake footway, paving, vehicular crossing (driveway), landscaping or stormwater\ndrainage works within a public footway or public road,\ne. Install utilities in, under or over a public road,\nf. Pump water into a public footway or public road from any land adjoining the public road,\ng. Erect a structure or carry out a work in, on or over a public road,\nh. Require a work zone on the public road for the unloading and or loading of vehicles,\ni. Pump concrete from within a public road,\nj. Stand a mobile crane within a public road,\nk. Store waste and recycling containers, skips, bins and/or buildi ng materials on any part of\nthe public road,\nl. The work is greater than $25,000, and\nm. Demolition is proposed.\nThe consent holder shall construct all works approved within the public road and footway under\nthe supervision and to the satisfaction of Council and shall arrange for necessary inspections by\nCouncil whilst the work is in progress.\nThe consent holder shall ensure that the person or company carr ying out the work will carry\npublic liability insurance to a minimum value of twenty million dollars and shall provide proof of\nthe policy to Council, before commencing any work approved by the Work Permit including the\nRoad Opening Permit. The policy must remain valid for the duration of the works.\n4.14. F i n i s h e d s u r f a c e l e v e l s o f a l l i n t e r n a l w o r k s a n d a t t h e s t r e e t boundary, including driveways,\nlandscaping and drainage structures, must be as shown on relevant construction certificate\nplans. The levels at the street boundary must be consistent with the Street Boundary Alignment\nLevels issued by Council.\nCouncil requires that the stormwater runoff from within the development site shall be collected\nand controlled in accordance with the approved stormwater and f lood management system as\ndocumented in the Costin Roe Consulting Stormwater Management Plan (Ref: CO14242.02-\n03c.rpt dated 4 September 2023), and the Flood Impact Risk Asse ssment Report by GRC Hydro\n(REF: 220040 dated 5 September 2023). The developer shall engage a suitably qualified engineer\nt o p r e p a r e a f i n a l s t o r m w a t e r d r a i n a g e a n d s t o r m w a t e r m a n a g e m e nt system plan to be\ngenerally in accordance with the concept plan in the table belo w, and in accordance with the\nrequirements contained in Council's Bankstown Development Engin eering Standards. The\nEngineer shall certify that the design and plans comply with Co uncil's Bankstown Development\nEngineering Standards and the relevant Australian Standards.\nThe report listed above shall be amended to reflect the following:\na. The pipe layout shall be as per plan number CO14242.02-DA, dated by 29/09/2023,\nRevision B, prepared by Costin Roe Consulting.\nb. All pit with diversion pipes shall have in situ concrete at all bends to direct runoff to the\npit outlet pipe.\nc. The north western flood storage area shall have multiple mainte nance access openings\nto allow for access maintenance and inspection.\n4.15. Sites located adjacent to Council’s drainage easement and/or sites affected by flooding shall\ncomply with the following:\na. No footings or permanent structural loading items shall be proposed within the new\nproposed easements over the diverted pipes.\nb. Where structures are located above the zone of influence of Council’s pipe, concrete pier\nand beam type footings shall be provided for all structures adjacent to Council’s proposed\nstormwater pipe and easement in accordance with the requirement s contained in\nCouncil's Bankstown Development Engineering Standards. Plans an d details prepared by\na qualified practising structural engineer, with details suitab le for construction in\naccordance with the above Policy shall be incorporated into the details for approval of the\nconstruction certificate. A copy of the approved details togeth er with a report prepared\nby a registered surveyor showing location, size and depth of the stormwater system, shall\nbe sent to Council for recordkeeping.\nc. All floor coverings over the new easements shall be asphaltic concrete.\nd. full depth construction joints shall be provided along the ease ment boundaries, in\naccordance with the requirements contained in Council's Banksto wn Development\nEngineering Standards / Canterbury Development Control Plan 2012 Part B5. Details\nsuitable for construction prepared by a qualified professional civil engineer shall be\nsubmitted to the principal before the issue of the construction certificate. A copy of the\napproved details shall be submitted to Council for recordkeeping.\n4.16. The minimum finished floor level shall not be less than RL 23.5 0m AHD for all industrial units\nfinished floor levels.\n4.17. The design, layout, signage, line marking, lighting and physica l controls of all off-street parking\nfacilities must comply with the minimum requirements of Austral ian Standard AS/NZS 2890.1\nParking facilities Part 1: Off-street car parking, AS/NZS 2890.2 Parking facilities Part 2: Off-street\ncommercial vehicle facilities and AS/NZS 2890.6 Parking facilit ies Part 6: Off-street parking for\npeople with disabilities. The details must be submitted to and approved by the certifier before\na construction certificate being issued.\nFurthermore, for internal driveways with a gradient exceeding 10% (1 in 10), longitudinal\nprofiles of all vehicular driveways and ramps shall be submitted for approval by the certifier\nbefore the issue of the construction certificate. The maximum grade of the driveway/ramp shall\nnot exceed 25% and shall comply with AS 2890 parking series. Th e profile shall be drawn at a\nreduction ratio of 1 to 25 vertical and horizontal and shall be related to the datum used for the\nissue of the footway design levels and shall also show the road centre line levels, Council issued\nfootway design levels and gutter levels. Council's Car Clearance Profile in Council's Development\nEngineering Standards, (Plan No. S 006) shall be used to design the profile.\n4.18. An all-weather pavement shall be designed to withstand the anticipated wheel loads for all areas\nsubjected to vehicular movements. Internal pavements specification prepared and certified by\na qualified professional Civil Engineer to comply with the relevant Australian Standards, shall be\nsubmitted to the certifier for approval before the issue of a construction certificate.\n4.19. Before the issue of any construction certificate for this devel opment, the consent holder must\nobtain approval from Council’s Traffic Section for a Site, Pede strian and Traffic Management\nPlan (SPTMP). This Plan must address the measures that will be implemented for pedestrian\nsafety and traffic management as specified below.\nA PRIVATE CERTIFIER CANNOT APPROVE YOUR SITE, PEDESTRIAN & TRAFFIC MANAGEMENT\nPLAN\nThis plan shall include details of the following:\na. Proposed ingress and egress points for vehicles to and from the construction site;\nb. Proposed protection of pedestrians, adjacent to the constructions site;\nc. Proposed pedestrian management whilst vehicles are entering/exi ting the construction\nsite;\nd. Proposed method of loading and unloading excavation machines, b uilding material,\nconstruction materials and waste containers during the construction period;\ne. Proposed traffic control measures such as advanced warning sign s, barricades, warning\nl i g h t s , a f t e r h o u r s c o n t a c t n u m b e r s e t c . a r e r e q u i r e d t o b e d i splayed and shall be in\naccordance with Council's and th e NSW Roads and Maritime Servic es requirements and\nAS1742.3.\nf. Proposed route for transportation of bulk and excavation materials to and from the\ndevelopment site.\nThe route for transportation to and from the development site o f bulk construction and\nexcavation materials sh all be by the shortest practical route t o the nearest \"State Road\", with\nevery effort to avoid school zones on public roads. . Alternate longer routes will only be\nconsidered in order to bypass school zones during school zone hours. If school zones cannot be\navoided n o h e a v y c o n s t r u c t i o n v e h i c l e m o v e m e n t s a r e t o a r r i v e o r d e p a rt the site during\nsignposted school zone periods 8:00am - 9:30am and 2:30pm - 4:0 0pm on school days. The\nconsent holder shall nominate the routes for approval by Council before commencement of any\nwork on the site. All vehicles are to enter the on-street Works Zone adjacent to the site in a\nforward direction. U-turn and right-turn movements into the site, are generally not permitted.\nA n A g r e e m e n t t o C o u n c i l ' s s a t i s f a c t i o n , s i g n e d b y t h e c o n s e n t holder/owner specifying the\napproved route and acknowledging responsibility to pay Council for damages to public property\na d j a c e n t t o t h e s i t e a n d f o r l o c a l r o a d s a l o n g t h e t r a n s p o r t a t ion routes shall be lodged with\nCouncil before release of any Construction Certificate. All dam age must be rectified upon\ncompletion of work.\nDamage will be rectified as required by Council to remove unsaf e conditions. All damage must\nbe rectified upon completion of work to the satisfaction of Council.\nThe approved Site, Pedestrian and Traffic Management Plan is to be implemented before the\ncommencement of any works on the construction site.\nIn addition, a TfNSW (formerly RMS) Approval / Road Occupancy L icence will be required for\nworks on Regional or State Roads or within 100m of a traffic fa cility including roundabouts and\ntraffic signals. Refer to Council's Development Engineering Sta ndards for a list of Regional and\nState Roads.\nN o t e : A p p r o v a l b y C o u n c i l o f a S P T M P m a y t a k e u p t o s i x ( 6 ) m o nths. Accordingly, it is\nrecommended the application to Council be submitted well in adv ance of the need for a\nconstruction certificate.\n4.20. The route for transportation to and from the development site of bulk and excavation materials\nshall generally be by the shortest possible route to the nearest \"regional road\", with every effort\nto avoid school zones on public roads. The consent holder shall nominate the route for approval\nb y C o u n c i l b e f o r e c o m m e n c e m e n t o f a n y w o r k o n t h e s i t e . A n \" A g reement\" to Council's\nsatisfaction, signed by consent holder specifying the approved route and acknowledging\nresponsibility to pay Council for damages to public property adjacent to the site shall be lodged\nwith Council before release of any construction certificate. All damage must be rectified before\nthe issue of any occupation certificate.\n4.21. Sight triangles are to be marked on relevant plans, being provided at the intersection of the\ndriveway and the property boundary in accordance with AS 2890.1: ‘Figure 3.3 - Minimum Sight\nLines for Pedestrian Safety’. A splay extending 2 metres from the driveway edge along the front\nboundary and 2.5 metres from the boundary along the driveway sh all be provided to give clear\nsight lines of pedestrians from vehicles exiting the site and i s to be kept clear of any obstacles.\nAny structures, plantings or fencing within these triangles is to be a maximum height of 600mm\nto ensure sight lines are kept clear of any obstacles. This shall be illustrated on plans submitted\nwith the construction certificate.\n4.22. Before the issue of a construction certificate, a Site Water Management plan shall be submitted\nto Council for review and endorsement. The Site Water Managemen t plan must be prepared in\naccordance with Part B4 of the Bankstown DCP 2015.\n4.23. B e f o r e t h e i s s u e o f a c o n s t r u c t i o n c e r t i f i c a t e , a n E n e r g y P e r f ormance Report, prepared by a\nsuitably qualified energy consultant, shall be submitted to Council for review and endorsement.\nThe Energy Performance Report must be prepared in accordance with Part B4 of the Bankstown\nDCP 2015.\n4.24. The construction certificate plans shall include details of the waste bin storage area. The bin\nstorage area shall not be visible from the street. The bin storage area shall be located within the\nbuilding or screened from the street by dense landscaping.\n4.25. A Trade Waste Agreement shall be obtained from Sydney Water bef ore the discharge of trade\nwastewater to the sewer system. Wastewater treatment equipment is to be bunded and where\nsystems are placed outside, they are to be roofed to ensure tha t no rainwater can enter the\nbund. All wastewater treatment devices shall be regularly maint ained in order to remain\neffective. All solid and liquid wastes collected from the device must be disposed of in accordance\nwith the Protection of the Environment Operations Act 1997.\n4.26. The certifier must not issue a construction certificate unless provided with detailed plans that\nform part of the construction certificate for the waste management areas that comply with the\nfollowing requirements as well as the requirements of Council’s “Waste Management Guide for\nNew Developments”:\na. Floors must be constructed of concrete at least 75mm thick and graded and drained to\na Sydney Water approved drainage fitting;\nb. Floors must be finished so as to be non-slip with a smooth and even surface;\nc. A designated room or enclosure and is to have a roof, with a mi nimum 2.1m\nunobstructed room height. A minimum 2.7m unobstructed room heig ht is required if\nbin lifting equipment is required;\nd. Must be compatible with the overall design of the development;\ne. Walls must be constructed of solid impervious material;\nf. Ceilings must be finished with a smooth faced non-absorbent material capable of being\ncleaned;\ng. Walls, ceiling and floors must be finished in a light colour;\nh. An adequate supply of hot and cold water mixed through a centralised mixing valve with\nhose cock is to service the room;\ni. A self-closing door openable from within the room;\nj. Must be constructed to prevent the entry of birds and vermin;\nk. Be provided with adequate light and ventilation. Light source m ust be through\ncontrolled light switches located both outside and inside the room;\nl. Any doorways must be 2 metres wide and open outwards; and\nm. Designed to fit the following bin allocations:\n4.27. Before the issue of any construction certificate, the certifier must receive written confirmation\nfrom Council, that Council has been provided to its satisfaction with the following:\na. Detailed plans showing that the waste storage rooms identified on stamped plans will be\ncapable of being accessed from the designed access roadway by a Heavy Rigid Vehicle (HRV)\ni n a c c o r d a n c e w i t h A S 2 8 9 0 . 2 , a n d t h a t a l o a d i n g a r e a i s a v a i l a bl e f o r t h e v e h i c l e w h e n\ncollecting waste that meets the following requirements:\ni. Within 5 metres of all waste storage rooms or temporary holding area;\nii. A separate parking area for the collection vehicle; and\niii. Include an extra 2 metres at the rear of the vehicle loading area.\nb. Certification from a suitably qualified engineer that the route of travel, loading area and\nentry and exit points will be constructed so as to support the following loading requirements:\ni. Heavy Rigid Vehicle can enter and exit the site in a forward position;\nii. 30 tonne waste collection vehicles;\niii. Turning circle of 25 metres;\niv. Length of 12 metres;\nv. Clearance height of 4.5 metres\n4.28. A detailed landscape plan prepared by a qualified landscape architect or qualified landscape\ndesigner must be approved by the certifier before the issue of a construction certificate. The\nlandscape plan must be prepared in accordance with Bankstown DCP 2015 and must include the\nfollowing features, notations and specifications:\na. The location of existing and proposed structures on the subject property/properties,\nincluding existing and proposed trees, impermeable areas, landscaped areas, deep soil\nzones, fixed furniture, shade structures, lighting, and other features,\nb. Details of earthworks and soil depths, including mounding and retaining walls and planted\nboxes,\nc. The location, number, pot size and type of chosen plant species. Details of planting\nprocedures and long-term maintenance (if any), and\nd. One 75ltr (minimum) major canopy tree shall be planted within t he front setback to the\ndevelopment, and\ne. Details of drainage and watering systems (if any).\n4.29. Approval in accordance with Council’s Tree Management Order (TMO ) i s g r a n t e d t o l o p o r\nremove only those trees identified to be lopped or removed on the approved plans. If not\nindicated on the approved plans, separate approval must be obtained to prune or remove trees\non adjoining properties or other trees located on the site. A person(s) who contravenes or causes\nor permits the TMO to be breached shall be guilty of an offence and liable for prosecution.\n4.30. Prior to the issue of a Construction Certificate relating to an y building works, the site is to be\nremediated in accordance with:\ni. The Remedial Action Plan, prepare d b y D e x u s P r o p e r t y G r o u p P t y Ltd dated 8 March\n2023, reference: RAP_149 Orchard Rd_Feb 2023_PS131192-SYD-REP-Rev2_FINAL;\nii. State Environmental Planning Policy No. 55 - Remediation of Land;\niii. The guidelines in force under the Contamination Land Management Act 1997; and\niv. The Site Audit advice prepared by Senversa Pty Ltd, titled Site Audit 149 Orchard Road,\nChester Hill IAA#6: WSP Remediation Action Plan (final V2) - Ma rch 2023, Reference:\nS19787_LET06_30March2023\nThe applicant must engage an appropriately qualified and experienced environmental consultant\nto supervise all aspects of site remediation and validation.\nAny variations to the approved remedial action plan must be submitted to and approved in\nwriting by an NSW EPA Accredited Site Auditor prior to the continuing of such work.\n4.31. Prior to issue of the constructio n certificate the proponent mu st submit a detailed validation\nreport to Council.\nThe validation report must be prepared in accordance with:\nI. ‘Managing Land Contamination: Planning Guidelines (Department of Urban Affairs and\nPlanning and NSW EPA, 1998);\nII. Relevant EPA Guidelines, noting the guidelines for ‘Consultants Reporting of\nContaminated Land 2020 and\nIII. National Environmental Protection (Assessment of Site Contamination) Measure 1999\n(as amended 2013).\nThe validation report must be prepared or reviewed and approved by an appropriately qualified\nenvironmental consultant.\nThe validation report must verify that the land is suitable for the proposed use(s), and that the\nremediation and validation of the site has been undertaken in accordance with the Remedial\nAction Plan prepared Dexus Property Group Pty Ltd titled, “Remediation Action Plan, 149 Orchard\nRoad, Chester Hill, NSW , dated 17 March 2023, reference: RAP_149 Orchard Rd_Feb\n2023_PS131192-SYD-REP-Rev2_FINAL;\n5. Conditions to be Satisfied Before Construction.\n5.1. The demolition of all structures on the property must be undert aken in accordance with all the\nfollowing:\n1. Written notice must be issued to adjoining residents and neighb ouring (industrial)\nproperties a minimum of seven (7) days before the commencement of demolition advising\nof the commencement date,\n2. Written notice must be issued to Council for inspection a minimum of (7) days before the\ncommencement of demolition. Written notice must include the date when demolition\nwork will commence and details of the name, address, contact te lephone number and\nlicence number of the demolition contractor,\n3. Inspections being undertaken by Council including:\n1. A pre-commencement demolition inspection when all site works required as part of\nthis Determination Notice are installed on the site and before demolition work\ncommencing, and\n2. A final demolition inspection when the demolition work has been completed to\nensure that the site is left in a satisfactory manner, in accordance with the conditions\nof this Determination Notice,\n4. Payment of an inspection fee at Council’s current rate must be paid before inspection.\nCouncil requires 48 hours’ notice to carry out an inspection,\n5. A sign must be erected at the front of the property showing the name of the licenced\ndemolition contractor, the licence number and a telephone number on which that person\ncan be contact outside of working hours,\n6. All demolition work must be carried out in accordance with Aust ralian Standard 2601 -\n‘The Demolition of Structures’,\n7. Where asbestos containing materials are to be removed, demoliti on must be carried out\nby contractors who have a current SafeWork NSW licence in asbestos removal,\n8. An asbestos clearance certificate issued under the Work Health and Safety Act 2011 must\nbe submitted to Council after the completion of demolition work,\n9. Hazardous and intractable wastes arising from the demolition pr ocess must be removed\nand disposed of in accordance with the requirements of SafeWork N S W a n d t h e N S W\nEnvironment Protection Authority,\n10. Demolition procedures must maximise the reuse and recycling of demolished materials\nto reduce the environmental impacts of waste disposal,\n11. Adhere to the requirements stipulated in the approved Waste Management Plan, and\n12. Demolition may only be carried out between 7.00 am and 5.00 pm on Monday to Saturday\nand no building work/s is to be carried out at any time on a Sunday or a public holiday.\nA copy of the final demolition inspection report must be submitted to the principal certifier\nbefore the commencement of any building work.\n5.2. A construction certificate is required for the erection of a building in accordance with this\nDetermination Notice.\nThis Determination Notice does not authorise building work unti l a principal certifier has been\nappointed as the principal certifier for the work by (or with the approval of) the consent holder.\nThe following requirements apply before the commencement of bui lding work in accordance\nwith this Determination Notice:\na. the principal certifier has, no later than two (2) days before the building work commences,\nnotified the Consent Authority and the Council (if the council is not the Consent Authority)\nof their appointment as the principal certifier,\nb. the principal certifier has, no later than two (2) days before the building work commences,\nnotified the consent holder of any inspections that are required t o b e c a r r i e d o u t i n\nrespect of the building work,\nc. the person carrying out the building work has notified the principal certifier that the\nperson will carry out the building work as an owner-builder, if that is the case,\nd. the consent holder, if not carrying out the work as an owner-builder, has:\ni. appointed a principal contractor for the building work who must be the holder of a\ncontractor licence if any residential building work is involved, and\nii. notified the principal certifier of the appointment, and\niii. unless that person is the principal contractor, notified the principal contractor of any\ninspections that are required to be carried out in respect of the building work,\ne. the consent holder has given at least a 2-day notice to the Council, and the principal\ncertifier if not the Council, of the person’s intention to commence the erection of the\nbuilding.\n5.3. A fence must be erected around the area of the development site, except where an existing 1.8\nmetres high boundary fence is in good condition and can secure the area. Any new fencing must\nbe temporary and at least 1.8 metres high. All fencing must be maintained throughout the\nconstruction period to ensure that the work area is secured.\nWhere the work is located within 3.6m of a public place, then a Type A or Type B hoarding must\nbe constructed appropriate to the work proposed. An application for a Work Permit for such\nhoarding must be submitted to Council for approval before the commencement of building\nwork/s.\n5.4. Before the commencement of any site or building work, the princ ipal certifier must ensure the\nadjoining building owner(s) is provided with a copy of the dila pidation report for their\nproperty(ies) no less than 14 days before the commencement of any site or building works.\n5.5. Before the commencement of work, the consent holder must provide a temporary on-site toilet\nif access to existing toilets on site is not adequate/available . Temporary on-site toilet facilities\nmust be installed and be adequately maintained throughout the construction period.\n5.6. Before the commencement of any site or building work, the principal certifier must be satisfied\nthe erosion and sediment controls in the erosion and sediment c ontrol plan, (as approved by\nthe principal certifier) are in place until the site is rectifi ed (at least 70% ground cover achieved\nover any bare ground on site).\n5.7. Council’s warning sign for Soil and Water Management must be displayed throughout the\nconstruction period at the most prominent point of the site, visible to both the street and site.\n5.8. A sign must be erected in a prominent position on any site on which building work or demolition\nwork is being carried out:\n1. showing the name, address and telephone number of the principal certifier for the work,\nand\n2. showing the name of the principal contractor (if any) for any b uilding work and a\ntelephone number on which that person may be contacted outside working hours, and\n3. stating that unauthorised entry to the work site is prohibited.\nAny such sign is to be maintained while the building work or de molition work is being carried\nout but must be removed when the work has been completed.\nNote: This does not apply in relation to building work or demolition w or k t hat i s c ar r i ed ou t\ninside an existing building that does not affect the external walls of the building.\n5.9. Before demolition, the entire site (including any structures) i s to be assessed for hazardous\nmaterials, especially asbestos. A Hazardous Materials (HAZMAT) Report is to be prepared by\na Type “A” inspection body accredited by NATA.\nAll recommendations in the above-mentioned report are to be implemented and a clearance\ncertificate issued by an appropriately qualified occupational h ygienist is to be submitted to\nCouncil before the commencement of demolition works.\n5.10. Before the commencement of any site or building work, the princ ipal certifier must ensure the\nmeasures for tree protection detailed in the construction site management plan are in place.\n6. Conditions to be Satisfied During Construction.\n6.1. While building work is being carried out, any such work must not continue after each critical\nstage inspection unless the principal certifier is satisfied the work may proceed in accordance\nwith this consent and the relevant construction certificate.\n6.2. Building work must be carried out in accordance with the requirements of the Building Code of\nAustralia (BCA).\n6.3. The construction and fixing of the signage is to be carried out in accordance with details\nprepared by a suitably qualified practising structural engineer, in accordance with the structural\nprovisions of the Building Code of Australia (BCA).\n6.4. Building work or demolition work m ay only be carried out betwee n 7.00 am and 6.00 pm on\nMonday to Friday, or between 8.00 am and 1.00 pm on Saturdays, and no construction is to be\ncarried out at any time on a Sunday or a public holiday.\n6.5. While building work is being carried out and where no noise and vibration management plan is\napproved under this consent, the consent holder is to ensure th a t a n y n o i s e c a u s e d b y\ndemolition, vegetation removal or construction does not exceed a n L A e q ( 1 5 m i n ) o f 5 d B ( A )\nabove background noise, when measured at any lot boundary of th e property where the\nconstruction is being carried out.\n6.6. While building work is being carried out, a registered surveyor i s t o m e a s u r e a n d m a r k t h e\npositions of the following and provide them to the principal certifier -\n1. All footings/ foundations\n2. At other stages of construction - any marks that are required by the principal certifier.\n6.7. All civil and hydraulic engineering works on site must be carried out in accordance with Council's\nBankstown Development Engineering Standards. All Civil and Hydraulic engineering works\nassociated with Council's assets and infrastructure must be carr i e d o u t i n a c c o r d a n c e w i t h\nCouncil's Work Permit requirements and to Council's satisfaction.\n6.8. The stormwater drainage system shall be constructed in accordan ce with Council's Bankstown\nDevelopment Engineering Standards and the engineering plans and d e t a i l s a p p r o v e d b y t h e\nprincipal certifier. Should the consent holder encounter any ex isting, live, underground\nstormwater drainage pipes, which carry flow from upstream prope r t i e s , t h e n t h e y m u s t\nmaintain the stormwater flow and re-route the stormwater pipes around the subject building or\nstructures at their own expense.\n6.9. Works on downstream properties is to be carried out in accordance with the following:\na. The owners of the adjacent property shall be given at least seven (7) days’ notice in writing\no f i n t e n t i o n t o c o m m e n c e w o r k w i t h i n t h e i r p r o p e r t y , t o g e t h e r with particulars of the\nproposed work.\nb. Where drainage excavation work s extend below the level of th e base of the footings of\nbuildings the consent holder shall, at his own expense: -\ni. Preserve and protect such building from damage; and\nii. If necessary, underpin and support such buildings.\nc. Restoration of drainage works in on adjacent property shall be to the satisfaction of the\nowners of the property/these properties.\n6.10. A suitably qualified Professional Civil or Structural Engineer shall be engaged by the developer\nto carry out inspections relatin g to construction of internal d riveways and parking areas. The\nwork shall be carried out in accordance with the approved plans and specifications and\ncertification from the Civil or Structural Engineer is to be provided upon completion.\n6.11. While building work is being carried out, the consent holder mu st pay any costs incurred as a\nresult of the approved removal, relocation or reconstruction of infrastructure (including ramps,\nfootpaths, kerb and gutter, light poles, kerb inlet pits, servi ce provider pits, street trees or any\nother infrastructure in the street footpath area).\n6.12. Any fill imported onto the site must be virgin excavated natura l material or excavated natural\nmaterial, classified as such in accordance the ‘Waste Classification Guidelines’ (NSW EPA, 2014)\nor excavated natural material meeting the requirements of the Excavated Natural Material\nExemption (NSW EPA, 2014).\nCertificates verifying that imported fill is virgin excavated natural material or excavated natural\nmaterial must be provided to Council prior to the issue of an Occupation Certificate.\nAll imported fill must be compatible with the existing soil characteristics of the site.\n6.13. All soils and material(s), liquid and solid, to be removed from the site must be analysed and\nclassified by an appropriately qualified and experienced enviro nmental consultant, in\naccordance with the Protection o f the Environment Operations (W aste) Regulation 2014 and\nrelated guidelines, in particular the ‘Waste Classification Gui delines’ (NSW EPA, 2014), prior to\noff-site disposal.\nThe waste classification report, including the results of testi ng, must be compiled, or reviewed\nand approved by an appropriately qualified and certified consul tant, and must be submitted to\nand approved by the Principal Certifying Authority before off-s ite disposal. A copy of the waste\nclassification report must be submitted to Council prior to issuing of an Occupation Certificate.\nAll waste material(s) must be disposed of at an appropriately licensed waste facility for the\nspecific waste. Receipts for the disposal of the waste must be submitted to Council prior to\nissuing of an Occupation Certificate.\n6.14. All excavations must be kept free from the accumulation of water. Prior approval must be sought\nfrom Council to discharge any water into the Council’s stormwater drainage system. Other\noptions for the disposal of water include disposal to sewer with prior approval from Sydney\nWater, or off-site disposal by a liquid waste transporter for t reatment/disposal to an\nappropriate waste treatment/processing facility.\nIn the instance works cause the generation of odours or uncovering of unexpected contaminants\nworks are to immediately cease, Council is to be notified and a suitably qualified environmental\nconsultant appointed to further assess the site. The exposed material/excavation is to be\nevaluated by the supervising environmental consultant and an ap propriate response\ndetermined in consultation with the applicant, which is agreed to by Council.\nCouncil may also request that an NSW EPA Accredited Site Auditor is involved to assist with the\nassessment of any unexpected finds, review any contamination information and prepare a site\naudit report and site audit statement. The applicant must adher e to any additional conditions\nwhich may be imposed by the NSW EPA Accredited Site Auditor.\n6.15. All excavations and backfilling must be executed safely and in accordance with the relevant\nAustralian Standards.\nI f t h e d e v e l o p m e n t i n v o l v e s a n e x c a v a t i o n t h a t e x t e n d s b e l o w t he l e v e l o f t h e b a s e o f t h e\nfootings of a building, structure or work (including any struct ure or work within a road or rail\ncorridor) on adjoining land, the consent holder must, at their own expense:\na. Protect and support the building, structure or work from possible damage from the\nexcavation, and\nb. Where necessary, underpin the building, structure or work to prevent any such damage.\nThis consent condition does not apply if the consent holder owns the adjoining land or the\nowner of the adjoining land has given consent in writing to that condition not applying.\nThe owner of any affected buildings is not liable for any part of the cost of work carried out for\nthe purposes of this clause, whether carried out on the allotment of land being excavated or on\nan adjoining allotment of land.\n6.16. I f t h e d e v e l o p m e n t i n v o l v e s a n e x c a v a t i o n t h a t e x t e n d s b e l o w t he l e v e l o f t h e b a s e o f t h e\nfootings of a building, structure or work on adjoining land (including any structure or work within\na road or rail corridor), the consent holder must, at their own expense -\n1. Protect and support the building, structure or work from possible damage from the\nexcavation, and\n2. Where necessary, underpin the building, structure or work to prevent any such damage.\nThis condition does not apply if the consent holder owns the adjoining land or the owner of the\nadjoining land has given consent in writing to that condition not applying.\n6.17. If soil conditions require it, retaining walls or other approved methods of preventing movement\nof the soil must be provided, and adequate provisions must be m ade for drainage. Should it be\nrequired, separate approval must be obtained for retaining walls.\n6.18. While building work, demolition or vegetation removal is being carried out, the principal certifier\nmust be satisfied all waste management is undertaken in accorda nce with the approved waste\nmanagement plan.\nUpon disposal of waste, the consent holder is to compile and provide records of the disposal to\nthe principal certifier, detailing the following:\n The contact details of the person(s) who removed the waste\n The waste carrier vehicle registration\n The date and time of waste collection\n A description of the waste (type of waste and estimated quantity) and whether the waste\nis expected to be reused, recycled or go to landfill\n The address of the disposal location(s) where the waste was taken\n The corresponding tip docket/receipt from the site(s) to which the waste is transferred,\nnoting date and time of delivery, description (type and quantity) of waste.\nNote: I f w a s t e h a s b e e n r e m o v e d f r o m t h e s i t e u n d e r a n E P A R e s o u r c e Recovery Order or\nExemption, the consent holder is to maintain all records in rel ation to that Order or Exemption\nand provide the records to the principal certifier and Council.\n6.19. The requirements of the submitted Waste Management Plan shall be complied with at all times\nthat work is being carried out. Without limiting the foregoing, compliance shall include the\nfollowing:\na. The disposal of any demolition and construction waste must be undertaken in accordance\nwith the requirements of the Protection of Environment Operations Act 1997; and\nb. All waste on site is to be stored, handled and disposed of in such a manner as to not create\nair pollution, offensive noise or pollution of land and water a s defined by the Protection\nof Environment Operations Act 1997; and\nc. Generation, storage, treatment and disposal of hazardous waste is conducted in\naccordance with the relevant waste legislation administered by the EPA and relevant\nOccupational Health and Safety legislation administered by WorkCover NSW; and\nd. All waste generated (including excavated materials) which canno t be reused or recycled\nmust be transported to a facility which can lawfully accept it; and\ne. Records are required regarding the details and location of the disposal of all demolition\nand construction waste (including excavated material), description of waste and are to be\nkept on site as evidences of lawful disposal. Records are to in clude receipts and\nweighbridge dockets which verify material types and volumes, time and date of disposal,\nwaste vehicle rego, and confirma tion of the waste disposal faci lity. Records/ details are\nalso to be kept of person removing the waste; and\nf. All materials and resources that are to be stored on site durin g construction works are\ncontained on the site; and\ng. The provisions of the Protection of Environment Operations Act 1997 must be complied\nwith when placing/stock piling loose material, disposal of concrete waste or activities\nwhich have potential to pollute drains and water courses; and\nh. T h e s t o r a g e o f w a s t e a n d r e c y c l i n g c o n t a i n e r s m u s t b e w i t h i n t he boundaries of the\ndevelopment site at all times. Public footways and roads must not be used for the storage\nof any waste and must be kept clear of obstructions during all construction works.\n6.20. There must not be any stockpiling of building spoil, materials, or storage of equipment on the\npublic road during the construction period. The footway and the road reserve must always be\nmaintained in a safe condition. No work can be carried out on t he public road, including the\nfootway, unless a Work Permit authorised by Council has been obtained.\n6.21. While vegetation removal, demolition and/or building work is be ing carried out, the consent\nholder must ensure the measures required by the approved construction site management plan\nand the erosion and sediment control plan are implemented at all times.\nThe consent holder must ensure a copy of these approved plans i s kept on site at all times and\nmade available to Council officers upon request.\n6.22. While site or building work is being carried out, the consent h older must maintain all required\ntree protection measures in good condition in accordance with t he construction site\nmanagement plan required under this consent, the relevant requi rements of AS 4970 -\n‘ P r o t e c t i o n o f t r e e s o n d e v e l o p m e n t s i t e s ’ a n d a n y a r b o r i s t ’ s report approved under this\nconsent. This includes maintaining adequate soil grades and ensuring all machinery, builders\nrefuse, spoil and materials remain outside tree protection zones.\n6.23. All work carried out on or around protected trees during demoli tion, clearing and construction\nshall comply with Australian Standard AS 4373 - ‘Pruning of amenity trees’ and Australian\nStandard AS 4970 - ‘Protection of trees on development sites’. Any site specific conditions\nrelating to tree protection shall take precedence over this requirement.\n6.24. If any trees to be retained and protected are threatened by dem olition, building or other site\nworks through accidental omission or unforeseen circumstances, the approving authority is to\nb e n o t i f i e d i m m e d i a t e l y i n w r i t i n g b e f o r e s u c h w o r k i s c o n t i n u ed so that this issue can be\nresolved.\n6.25. The following tree/s shall be retained and protected from removal and damage for the duration\nof the development:\n As Per Arboricultural Impact Assessment & Tree Protection Plan. Appendix B\n 1 x Ficus microcarpa var hilli within the primary frontage on Orchard Road\n 5 x Corymbia maculate along the north-east boundary adjoining Orchard Road\n* TPZ and SRZ in metres measured from the centre of the trunk of the tree.\nTree protection measures shall comply with Australian Standard AS4970-2009 Protection of trees\non development sites, together with the following conditions:\n The tree/s to be retained and protected together with their rel evant Tree Protection Zone\n(TPZ) and Structural Root Zone (SRZ) shall be marked on all dem olition and construction\ndrawings.\n The stormwater line and associated pits are to be located no closer than 3 metres from the\nretained trees. Alternatively, the stormwater line is to be ins talled by careful digging using\nhand tools or horizontal boring and passing the pipe beneath ex isting tree roots within 3\nmetre radius of the retained tree. No tree roots greater than 4 5mm in diameter are to be\nsevered.\n Exploratory excavation should be undertaken using non-destructive means (hydro set at\n1000psi or hand tools) to a depth of at least 800mm. The exploratory excavation should be\nsupervised by the Project Arborist who will 'map' the location of the roots and determine,\nbased on this assessment, whether Tree 45 can be retained or needs to be removed. Should\nthe exploratory mapping suggest that Tree 45 is required to be removed, the removal of\nTree 45 is approved by Council subject to owners’ consent being obtained.\n All contractors and workers on site shall be briefed on the tree protection and management\nprocedures in place as part of their site induction. A written record of the induction process\nis to be kept on site.\n A designated Tree Protection Zone shall be created on site by e recting a tree protection\nfence at 5 metre radius from the trunk of the Jacaranda mimosifolia (jacaranda). The fence\nis to be constructed of chain wire mesh 1.80 metres high supported by steel posts. The\nfence is to be installed prior to demolition / construction, sh all not be removed or altered,\nand is to remain in place for the duration of the site works;\n The applicant will display in a p rominent location on the tree protection fence a durable,\nweather resistant sign of a similar design, layout and type size as per Appendix C, Australian\nStandard AS4970-2009 Protection of trees on development sites clearly showing:\na. The Development Consent number;\nb. The name and contact phone number of the site manager;\nc. The purpose of the protection zone;\nd. The penalties for disregarding the protection zone;\n No vehicular access, excavations for construction or installation of services shall be carried\nout within the fenced Tree Protection Zone.\n All utility services, pipes, stormwater lines and pits shall be located outside the fenced Tree\nProtection Zone.\n Building materials, chemical storage, site sheds, wash out area s, and similar shall not be\nlocated within the fenced Tree Protection Zone.\n Trees marked for retention must not be damaged or used to display signage, or as fence or\ncable supports for any reason.\n If tree roots are exposed during approved works, roots with a diameter less than 25mm are\nto be pruned cleanly using sharp hand tools and not torn or ripped by machinery. Tree roots\ngreater than 25mm in diameter are to be assessed by a qualified arborist - minimum\nAustralian Qualification Framework (AQF) Level 4 or equivalent - before any pruning work\nis undertaken. If necessary, changes in design or relocation of works may be required.\n N o r i p p i n g o r r o t a r y h o e i n g w i t h i n t h e T r e e P r o t e c t i o n Z o n e o f trees to be retained is\npermitted.\n Any approved excavation within the Tree Protection Zone of protected trees must be\ncarried out by hand under the care and control of a qualified arborist - minimum Australian\nQualification Framework (AQF) Level 4 or equivalent - to avoid unnecessary damage to tree\nroots.\n In exceptional circumstances, the tree protection fencing may b e temporarily relocated to\nallow site access for construction purposes subject to the prior approval of the project\narborist, the installation of ground protection measures as det ailed below, and following\nthe clearly identified tagging of all protected trees, provided such fencing is immediately\nreplaced on completion of the wo rks. No damage to root systems or soil compaction will\nbe accepted during such works.\n I f t h e a p p r o v i n g a u t h o r i t y c o n s e n t s t o m a t e r i a l s , m a c h i n e r y o r access over specifically\nnominated areas of the tree protection zone, the roots and surface soil within this area shall\nbe mulched to a minimum depth of 100mm of hardwood wood chip ov erlaid with rumble\nboards, steel plates, or similar. This ground protection measure must be maintained for the\nduration of the site works.\n The trees are to be watered during dry spells, i.e. two to thre e weeks without adequate\nrainfall. The root zone should be thoroughly watered and then left to drain. A\ntemporary/permanent irrigation system is to be installed on sit e where works longer than\none month in duration are expected and when appropriate shall be part of the landscaping\nworks.\n Any pruning works shall be carried out by a qualified arborist and shall comply with\nAustralian Standard AS4373-2007 Pruning of Amenity Trees, the A menity Tree Industry -\nCode of Practice, 1998 (Workcover, NSW), and Guide to Managing Risks of Tree Trimming\nand Removal Work (Safe Work Australia 2016).\nAll other vegetation not specifically identified above, and pro t e c t e d b y C o u n c i l s T r e e\nManagement Order, is to be retained and protected from Construc tion damage and pruning.\nThe Tree Management Order protects trees over 5m in height.\n6.26. All work carried out on or around protected trees during demoli tion, clearing and construction\nshall comply with Australian Standard AS4373-2007 Pruning of amenity trees and Australian\nStandard AS4970-2009 Protection of trees on development sites. Site specific conditions relating\nto tree protection shall take precedence over this requirement.\n6.27. If any trees to be retained and protected are threatened by dem olition, building or other site\nworks through accidental omission or unforeseen circumstances, the approving authority is to\nb e n o t i f i e d i m m e d i a t e l y i n w r i t i n g b e f o r e s u c h w o r k i s c o n t i n u ed so that this issue can be\nresolved.\n6.28. While demolition or building work is being carried out, all suc h works must cease immediately\nif a relic or Aboriginal object is unexpectedly discovered. The consent holder must notify the\nH e r i t a g e C o u n c i l o f N S W i n r e s p e c t o f a r e l i c a n d n o t i f y t h e S ecretary of the Department of\nPlanning, Industry and Environment and the Heritage Council of NSW in respect of an Aboriginal\nobject. Building work may recommence at a time confirmed by eit her the Heritage Council of\nNSW or the Secretary of the Department of Planning, Industry and Environment.\nIn this condition:\n “relic” means any deposit, artefact, object or material evidence that:\na. relates to the settlement of the area that comprises New South Wales, not being\nAboriginal settlement, and\nb. is of State or local heritage significance; and\n “Aboriginal object” means any deposit, object or material evidence (not being a handicraft\nmade for sale) relating to the Aboriginal habitation of the area that comprises New South\nWales, being habitation before o r concurrent with (or both) the occupation of that area\nby persons of non-Aboriginal extraction and includes Aboriginal remains.\n7. Conditions to be Satisfied Before Occupation.\n7.1. The occupation or use of the building must not commence unless an occupation certificate has\nbeen issued.\n7.2. Registration of the drainage easements in accordance with the a pproved plans shall be\ncommenced before the issue of any occupation certificate.\n7.3. A Loading Management Plan must be submitted to and approved by the principal certifier\nbefore the issue of an occupation certificate.\nThe plan should identify how the loading area will be managed a nd used by all building tenants\nincluding retail and residential use such as for removal vehicles, bulky good deliveries and\nsimilar.\nThe plan must include, but is not limited to, management of del iveries to ensure there is no\nrequirement for any service vehicles to wait on public streets to enter the site.\nThe plan shall be managed either by a schedule showing all tenants when they can use the area,\nor by a register managed on site to allow tenants to reserve a time period for their deliveries.\nOnce approved, this management plan will need to be provided to all tenants and external users\nof the loading area.\n7.4. Eighty-two (82) off-street car parking spaces shall be provided and maintained for the use of\nvisitor and employees to the premises in accordance with the submitted plans. Such spaces are\nto be sealed and line marked and maintained for the lifetime of the development.\n7.5. A report as prepared by a registered surveyor must be submitted to the principal certifier\nverifying that the reduced level (RL) of the finished floor level at each level, the height of external\nwalls, the maximum reduced level (RL) of roof structures / roof eaves overhangs and the\nexternal wall setbacks to the property boundaries all conform with the approved plans.\n7.6. Before the issue of an occupation certificate, the holder of this consent is to plant replacement\ntrees on the site as follows:\n As per Landscape Plan. (Issue G, as dated 1.04.2023)\n Tree species used are not to include conifers, Casuarinaceae, p a l m s o r a n y o f t h e\nexempted species listed under clause 3.4 of Canterbury Developm ent Control Plan 2012\nPart B3 - Tree Management Order.\n The tree/s shall have a container size not less than 75 litres, shall comply with NATSPEC\nSpecifying Trees: a guide to a ssessment of tree quality (2003) or Australian Standard AS\n2303 - 2015 Tree stock for landscape use\n The tree/s shall be planted no closer than 3.5 metres from the wall of any approved\nbuildings on the property.\n The tree/s shall be planted so that future growth is not in conflict with overhead electricity\nwires.\n The tree/s shall be maintained for the life of the development.\n7.7. Before the issue of an occupation certificate, a registered surveyor must submit documentation\nto the principal certifier which demonstrates that:\na. n o e x i s t i n g s u r v e y m a r k ( s ) h a v e b e e n r e m o v e d , d a m a g e d , d e s t r o y ed, obliterated or\ndefaced, or\nb. the consent holder has re-established any survey mark(s) that were damaged, destroyed,\nobliterated or defaced in accordance with the Surveyor General’s Direction No. 11 -\n‘Preservation of Survey Infrastructure’.\n7.8. Before the issue of the relevant occupation certificate, the pr incipal certifier must ensure any\nadjustment or augmentation of any public utility services including gas, water, sewer, electricity,\nstreet lighting and telecommunications, required as a result of the development, is completed\nto the satisfaction of the relevant authority.\nBefore the issue of the occupation certificate, the principal certifier must request written\nconfirmation from the relevant authority that the relevant services have been completed.\n7.9. The Section 73 compliance certificate under the Sydney Water Act 1994 must be submitted to\nthe principal certifier before the issue of an occupation certificate.\n7.10. Before issue of an occupation certificate and following the completion, installation, and testing\nof all the mechanical ventilation systems, a Mechanical Ventilation Certificate of Completion\nand Performance in accordance with Clause A2.2 (a) (iii) of the Building Code of Australia, must\nbe submitted to the principal certifier.\n7.11. An occupation certificate must not be issued until all conditions relating to demolition, building\nand subdivision works have been satisfied and Council has issue d a Work Permit Compliance\nCertificate (where applicable).\n7.12. Before the issue of an occupation certificate, the consent hold e r m u s t e n s u r e a n y p u b l i c\ninfrastructure damaged as a result of the carrying out of building works (including damage\ncaused by, but not limited to, delivery vehicles, waste collect ion, contractors, sub-contractors,\nconcreting vehicles) is fully repaired to the written satisfacti o n o f C o u n c i l , a n d a t n o c o s t t o\nCouncil.\n7.13. The following signs must be provided and maintained within the site at the point(s) of vehicle\negress:\na. Compelling drivers to stop before proceeding onto the public way\nb. Compelling drivers to \" Give Way to Pedestrians \" before crossing the footway; or\ncompelling drivers to \" Give Way to Pedestrians and Bicycles \" before crossing a footway\non an existing or identified shared path route.\n7.14. Before the issue of any occupation certificate, an agreement must be entered into with Council\non terms satisfactory to Council for the collection of waste.\n7.15. Before the issue of an occupation certificate, the principal certifier must ensure all refuse, spoil\nand material unsuitable for use on-site is removed from the sit e and disposed of in accordance\nwith the approved waste management plan. Written evidence of the removal must be supplied\nto the satisfaction of the principal certifier.\nBefore the issue of a final occupation certificate, the consent holder must ensure the temporary\nstorage of any waste is carried out in accordance with the approved waste management plan to\nthe principal certifier’s satisfaction.\n7.16. B e f o r e t h e i s s u e o f a n o c c u p a t i o n c e r t i f i c a t e , t h e p r i n c i p a l c ertifier must be satisfied that all\nlandscape and tree-works, including pruning in accordance with AS 4373 - ‘Pruning of amenity\ntrees and the removal of all noxious weed species’, have been c ompleted in accordance with\nthe approved plans and any relevant conditions of this consent.\n7.17. Any lighting on the site shall be designed so as not to cause nuisance to other residences in the\narea or to motorists on nearby public roads and to ensure no adverse impact on the amenity of\nthe surrounding area by light overspill. All lighting shall comply with the Interim Australian\nStandard AS 4282 - ‘The Control of the Obtrusive Effects of Outdoor Lighting’.\n7.18. An Emergency Response Management Plan shall be prepared and sub mitted to Council's\nsatisfaction. The Plan shall include the following:\na. List of chemicals and maximum quantities to be stored at the site;\nb. Identification of potentially hazardous situations;\nc. Procedure for incident reporting;\nd. Details of spill stations and signage;\ne. Containment and clean-up facilities and procedures; and\nf. The roles of all staff in the plan and details of staff training.\n7.19. Where the Validation Report identifies the need for the impleme ntation of an ongoing\nenvironmental management plan, the plan must be submitted to Council and the Principal\nCertifying Authority. The ongoing environmental management plan must be prepared in\naccordance with:\ni. NSW Contaminated Land Planning Guidelines;\nii. Relevant EPA endorsed guidelines; and\niii. National Environmental Protection (Assessment of Site Contamination) Measure 1999 (as\namended 2013).\nThe ongoing environmental management plan must be prepared or r eviewed and approved by\na suitably qualified environmental consultant.\nThe ongoing environmental management plan must be submitted to, and approved by, Council\nprior to the issue of an Occupation Certificate.\nThe ongoing environmental management plan must describe the nature and location of the\ncontamination and prescribe how the contaminants will be manage d/monitored and the\nresponsible parties for this management/monitoring in the long-term.\nThe ongoing environmental management plan must specifically outline the construction details,\nand the requirements of manageme nt and monitoring of the contai nment cell to ensure it is\nmaintained appropriately, its integrity remains intact, and to avoid migration of contamination.\nThe ongoing environmental management plan must also include a contingency plan if the\nsystems fail.\n7.20. The acoustic report submitted in support of this application, p repared by Acoustic Dynamics,\ntitled “Operational Noise Emission Assessment, 149 Orchard Road, Chester Hill, NSW, reference\nnumber: 571R001.JC.220912, dated 12 September 2022 and recommendations in section 5\nforms part of the development consent.\n8. Conditions of Use.\n8.1. The hours of operation of the use are 24 hours per day, 7 days per week.\n8.2. All loading and unloading operat ions associated with servicing the site must be carried out\nwithin the confines of the site, at all times and must not obst ruct other properties/units or\nthe public way.\nAt all times the service vehicle docks, car parking spaces and access driveways must be kept\nclear of goods and must not be used for storage purposes, including garbage storage.\n8.3. The approved car parking spaces, driveways and manoeuvring area s are to be used for\nemployees and visitors’ vehicles only and not for the storage of new or used materials, finished\ngoods or commercial vehicles.\n8.4. The flood storage area within the site as constructed shall not be altered and shall be maintained\nin good working order to the satisfaction of Council.\n8.5. During occupation and ongoing use of the building, the consent holder must ensure all\nwastewater and stormwater treatment devices (including drainage systems, sumps and traps,\nand flood storage area) are regularly maintained, to remain eff ective and in accordance with\nany positive covenant (if applicable).\n8.6. Any system using traffic light signals must maintain a green si gnal to entering vehicles at the\npoint of entry and must maintain a red signal when an exiting vehicle is detected upon the ramp\nor driveway. This is to ensure that vehicles entering the site do not have to wait at the top of\nthe ramp, and vehicles wishing to exit the site must wait for entering vehicle in the basement at\nthe waiting bay.\n8.7. All vehicles associated with the development are to enter and exit the site in a forward direction.\n8.8. The requirements of the submitted Waste Management Plan shall be complied with at all times\nthat the approved development is being carried out.\n8.9. The consent holder shall enter into a commercial contract for the collection of wastes and\nrecycling. A copy of the commercial waste and recycling contrac t shall be lodged with Council\nand invoices should be available for inspection at any time.\n8.10. All commercial uses must engage and utilise the services of a p rivate waste collection service\nand must have written evidence on site of a valid and current c ontract with a licenced waste\ncollector for waste and recycling collection disposal.\n8.11. All waste generated on the site is to be stored, handled and di sposed of in such a manner as to\nnot create offensive odour, offensive noise or pollution of lan d and/or water as defined under\nthe Protection of the Environment Operations Act 1997 . All waste generated shall be removed\na n d d i s p o s e d o f b y a n a u t h o r i s e d w a s t e r e m o v a l c o n t r a c t o r . A c opy of the waste removal\nagreement and receipts shall be made available to Council on request.\n8.12. No waste storage containers are to be located or placed outside the approved waste storage\narea at any time except for collection purposes.\n8.13. The consent holder shall ensure that all activities within the premises comply with the relevant\nsections of the Protection of the Environment Operations Act 1997 and Regulations and the NSW\nEnvironment Protection Authority Industrial Noise Policy (2000).\n8.14. The approved landscaping and external work must be maintained post occupation and must not\nbe altered or changed without Council approval or unless the altered work is carried out in\naccordance with the relevant provisions of the State Environmental Planning Policy (Exempt and\nComplying Development Codes) 2008.\n8.15. Instructions concerning procedures to be adopted in the event of an emergency are to be clearly\ndisplayed on the premises for both public and staff information at all times.\n8.16. Any retailing undertaken on the premises must be ancillary to t he main industrial use of the\npremises. The retailing sales area shall be restricted to a maximum of 15% of the total floor area\nas indicated on the approved plan.\n8.17. The operation of the premises must comply with the relevant sec tions of the Protection of the\nEnvironment Operations Act 1997 and the Noise Policy for Industry (2017) and shall not give rise\nto “offensive noise” as defined under the provisions of the Protection of the Environment\nOperations Act 1997.\n8.18. The use of the premises and the operation of plant and equipmen t must not give rise to the\ntransmission of a vibration nuisance or damage to other premise s as defined in the ‘Assessing\nVibration: A Technical Guideline’ (NSW Department of Environment and Conservation, 2006).\n8.19. Any lighting of the premises must be installed in accordance with AS 4282-1997, ‘Control of the\nobtrusive effects of outdoor lighting’, so as to avoid annoyanc e to the occupants of adjoining\npremises or glare to motorists on nearby roads. Flashing, movin g or intermittent lights or signs\nare prohibited. The intensity, colour or hours of illumination of the lights must be varied at\nCouncil’s discretion if Council considers there to be adverse effects on the amenity of the area.\n8.20. The operation of the development must not adversely affect the amenity of the neighbourhood\nor interfere unreasonably with the comfort or repose of a perso n who is outside the premises\nby reason of the emission or disc harge of noise, fumes, vapour, odour, steam, soot, ash, dust,\nwaste water, waste products, grit, oil or other harmful products.\n8.21. All waste generated on the site is to be stored, handled and di sposed of in such a manner as to\nnot create offensive odour, offensive noise or pollution of lan d and/or water as defined under\nthe Protection of the Environment Operations Act 1997 . All waste generated shall be removed\na n d d i s p o s e d o f b y a n a u t h o r i s e d w a s t e r e m o v a l c o n t r a c t o r . A c opy of the waste removal\nagreement and receipts shall be made available to Council on request.\n8.22. No mobile food vending vehicles or temporary food premises are permitted to operate at the\npremises without prior written consent from Council.","stage":"general","stage_basis":"heading","page":4}]});
